#!/usr/bin/env python3
"""List all paragraphs in document.xml with their style and text."""
import xml.dom.minidom

dom = xml.dom.minidom.parse("unpacked/word/document.xml")

W = "w"

def ns(tag):
    return tag.split(":")[-1]

for i, p in enumerate(dom.getElementsByTagName("w:p")):
    style = ""
    for pPr in p.getElementsByTagName("w:pPr"):
        for child in pPr.childNodes:
            if child.nodeType == child.ELEMENT_NODE and ns(child.tagName) == "pStyle":
                style = child.getAttribute("w:val")
    texts = []
    for r in p.getElementsByTagName("w:r"):
        for t in r.childNodes:
            if t.nodeType == t.ELEMENT_NODE and ns(t.tagName) in ("t", "delText"):
                texts.append(t.firstChild.nodeValue if t.firstChild else "")
    text = "".join(texts)
    print(f"[{i}] style={style!r} text={text!r}")

#!/usr/bin/env python3
"""Underline all headlines in the report's document.xml (stdlib-only)."""
import xml.dom.minidom

PATH = "unpacked/word/document.xml"

HEADLINES = {
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
}

dom = xml.dom.minidom.parse(PATH)


def para_text(p):
    parts = []
    for r in p.getElementsByTagName("w:r"):
        for t in r.childNodes:
            if (
                t.nodeType == t.ELEMENT_NODE
                and t.tagName.split(":")[-1] in ("t", "delText")
            ):
                parts.append(t.firstChild.nodeValue if t.firstChild else "")
    return "".join(parts)


updated = 0
for p in dom.getElementsByTagName("w:p"):
    if para_text(p) not in HEADLINES:
        continue
    for r in p.getElementsByTagName("w:r"):
        rPrs = r.getElementsByTagName("w:rPr")
        if not rPrs:
            rPr = dom.createElement("w:rPr")
            r.insertBefore(rPr, r.firstChild)
        else:
            rPr = rPrs[0]
        # Skip if already underlined
        if rPr.getElementsByTagName("w:u"):
            continue
        u = dom.createElement("w:u")
        u.setAttribute("w:val", "single")
        # Schema order for CT_RPr: ... sz, szCs, highlight, u, effect ...
        # Insert w:u after sz-cs/highlight (before effect/bdr/shd/...) if present
        anchor = None
        for tag in ("w:sz-cs", "w:highlight", "w:effect", "w:bdr", "w:shd"):
            found = rPr.getElementsByTagName(tag)
            if found:
                anchor = found[0]
        if anchor is not None:
            rPr.insertBefore(u, anchor.nextSibling)
        else:
            rPr.appendChild(u)
    updated += 1

assert updated == len(HEADLINES), f"Expected {len(HEADLINES)} headlines, updated {updated}"

with open(PATH, "wb") as f:
    f.write(dom.toxml(encoding="UTF-8"))

print(f"Underlined {updated} headline paragraphs")

